  <!-- Component Definitions -->
  <!-- Constants for layout -->
  <script type="text/ecmascript">
    const NODE_WIDTH = 280;
    const NODE_HEIGHT = 100;
    const H_GAP = 40;
    const V_GAP = 60;
    const PADDING = 15;
    const LINE_HEIGHT = 1.2;

    function createComponent(x, y, name, description, colorClass) {
      const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
      g.setAttribute("transform", `translate(${x}, ${y})`);

      const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("width", NODE_WIDTH);
      rect.setAttribute("height", NODE_HEIGHT);
      rect.setAttribute("class", `component-rect ${colorClass}`);
      g.appendChild(rect);

      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", PADDING);
      text.setAttribute("y", PADDING + 10);

      const nameTspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
      nameTspan.setAttribute("x", PADDING);
      nameTspan.setAttribute("dy", "0");
      nameTspan.setAttribute("class", "component-name");
      nameTspan.textContent = name;
      text.appendChild(nameTspan);

      const descLines = description.split('\n');
      descLines.forEach((line, index) => {
        const descTspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
        descTspan.setAttribute("x", PADDING);
        descTspan.setAttribute("dy", `${LINE_HEIGHT}em`);
        descTspan.setAttribute("class", "component-desc");
        descTspan.textContent = line;
        text.appendChild(descTspan);
      });
      g.appendChild(text);
      return g;
    }
  </script>

